/* cmux-next.json's reads for the app (cmux-tui/crates/cmux-app-ffi,
 * src/settings.rs): the JSON ops of cmux-config's app_ops, run by
 * cmux_settings_call. */

#ifndef CMUX_SETTINGS_H
#define CMUX_SETTINGS_H

/* Generated by cbindgen (cmux-tui/crates/cmux-app-ffi/cbindgen-settings.toml); do not edit.
 * Regenerate: CMUX_APP_FFI_HEADER_BLESS=1 cargo test --test settings_header (cmux-app-ffi) */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 Bumped on any change to a type, a function or an op.
 */
#define CMUX_SETTINGS_ABI_VERSION 1

/*
 The op ran; `*out` holds its reply.
 */
#define CMUX_SETTINGS_OK 0

/*
 A null pointer where one is required.
 */
#define CMUX_SETTINGS_ERR_NULL -1

/*
 Not UTF-8, or not the JSON the op takes.
 */
#define CMUX_SETTINGS_ERR_INVALID -2

/*
 The op is not one of cmux_config::app_ops's.
 */
#define CMUX_SETTINGS_ERR_UNKNOWN_OP -3

/*
 A panic inside, caught.
 */
#define CMUX_SETTINGS_ERR_PANIC -4

/*
 A reply buffer owned by the caller (JSON, UTF-8). `ptr` is null when `len`
 is 0.
 */
typedef struct {
    uint8_t *ptr;
    size_t len;
} CmuxSettingsBytes;

/*
 `CMUX_SETTINGS_ABI_VERSION`.
 */
uint32_t cmux_settings_abi_version(void);

/*
 Runs one JSON op: `op` (NUL-terminated, such as `jsonc.parse`) on
 `request` (a JSON object, UTF-8); `*out` gets the reply's JSON, which the
 caller frees with `cmux_settings_bytes_free`.

 # Safety

 `op` is a NUL-terminated string; `request_ptr` with `request_len` is
 readable; `out` is writable.
 */
int32_t cmux_settings_call(const char *op, const uint8_t *request_ptr, size_t request_len, CmuxSettingsBytes *out);

/*
 Frees a reply buffer. A null `ptr` is ignored.

 # Safety

 `bytes` came from `cmux_settings_call` and is freed once.
 */
void cmux_settings_bytes_free(CmuxSettingsBytes bytes);

#endif  /* CMUX_SETTINGS_H */
